mapper.select:
select * from comment


        and spu_id = #{spuId}


        and user_id = #{userId}


        and rating = #{rating}


        and status = #{status}


order by create_time desc, id desc

select c.id, c.spu_id, s.name as spu_name, sk.image as spu_image, c.user_id, u.name as user_name, u.phone as user_phone, u.avatar as user_avatar, c.content, c.images, c.rating, c.status, c.create_time from comment c left join shoe_spu s on c.spu_id = s.id left join shoe_sku sk on sk.spu_id = s.id and sk.is_default = 1 left join user u on c.user_id = u.id
and c.spu_id = #{spuId}
and c.user_id = #{userId}
and s.name like concat('%',#{spuName},'%')
and u.name like concat('%',#{userName},'%')
and c.rating = #{rating}
and c.status = #{status}
order by c.create_time desc, c.id desc
